using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;
using System.ComponentModel.DataAnnotations;
using WebServiceCore.Models;
using WebServiceCore.Models.Entities;
using WebServiceCore.Services;
namespace WebServiceCore.Pages;
[Authorize(Roles="admin")]
public class ReviewsModel(OnlineVideosDataContext db,SiteReviews reviews,PackageReview packages):PageModel {
 public List<SiteChange> Changes {get;set;}=[];
 public sealed record PackageItem(string Id,PackageReview.Pending Metadata);
 public List<PackageItem> Packages {get;set;}=[];
 public async Task OnGetAsync(){Changes=await db.SiteChanges.AsNoTracking().Where(x=>x.Status=="pending").OrderBy(x=>x.Created).Take(100).Select(x=>new SiteChange{Id=x.Id,Name=x.Name,OwnerId=x.OwnerId,Created=x.Created,Xml=x.Xml,RequiredDll=x.RequiredDll}).ToListAsync();if(Directory.Exists(packages.Root))foreach(var f in Directory.EnumerateFiles(packages.Root,"*.json").Take(100)){try{var id=Path.GetFileNameWithoutExtension(f);if(!Guid.TryParseExact(id,"N",out _) || new FileInfo(f).Length>16384)continue;var p=System.Text.Json.JsonSerializer.Deserialize<PackageReview.Pending>(await System.IO.File.ReadAllTextAsync(f));if(p!=null)Packages.Add(new(id,p));}catch(System.Text.Json.JsonException){}catch(FileNotFoundException){}}}
 public async Task<IActionResult> OnPostApproveTogetherAsync(int siteId,string packageId,string sha256){if(!Guid.TryParseExact(packageId,"N",out _)||string.IsNullOrEmpty(sha256))return BadRequest();try{await reviews.Decide(User.Identity.Name??"",siteId,true,packageId,sha256);return RedirectToPage();}catch(UnauthorizedAccessException){return Forbid();}catch(ValidationException ex){ModelState.AddModelError("",ex.Message);await OnGetAsync();return Page();}catch(FileNotFoundException){ModelState.AddModelError("","This package is no longer pending. Reload the reviews.");await OnGetAsync();return Page();}}
 public async Task<IActionResult> OnPostRejectTogetherAsync(int siteId,string packageId,string sha256){if(!Guid.TryParseExact(packageId,"N",out _)||string.IsNullOrEmpty(sha256))return BadRequest();try{await reviews.Decide(User.Identity.Name??"",siteId,false,packageId,sha256);return RedirectToPage();}catch(UnauthorizedAccessException){return Forbid();}catch(ValidationException ex){ModelState.AddModelError("",ex.Message);await OnGetAsync();return Page();}catch(FileNotFoundException){ModelState.AddModelError("","This package is no longer pending. Reload the reviews.");await OnGetAsync();return Page();}}
 public async Task<IActionResult> OnPostApprovePackageAsync(string id,string sha256){try{await packages.Approve(id,User.Identity.Name??"",sha256);return RedirectToPage();}catch(UnauthorizedAccessException){return Forbid();}catch(ValidationException ex){ModelState.AddModelError("",ex.Message);await OnGetAsync();return Page();}catch(FileNotFoundException){ModelState.AddModelError("","This package is no longer pending. Reload the reviews.");await OnGetAsync();return Page();}}
 public async Task<IActionResult> OnPostRejectPackageAsync(string id,string sha256){try{await packages.Reject(id,User.Identity.Name??"",sha256);return RedirectToPage();}catch(UnauthorizedAccessException){return Forbid();}catch(ValidationException ex){ModelState.AddModelError("",ex.Message);await OnGetAsync();return Page();}catch(FileNotFoundException){ModelState.AddModelError("","This package is no longer pending. Reload the reviews.");await OnGetAsync();return Page();}}
 public async Task<IActionResult> OnGetDownloadPackageAsync(string id,string sha256){try{var package=await packages.ReadForReview(id,User.Identity.Name??"",sha256);Response.Headers.CacheControl="no-store";Response.Headers["X-Content-Type-Options"]="nosniff";return File(package.Bytes,"application/octet-stream",package.Name+".dll");}catch(UnauthorizedAccessException){return Forbid();}catch(ValidationException){return BadRequest("Package validation failed. Reload the reviews.");}catch(FileNotFoundException){return NotFound();}}
 public async Task<IActionResult> OnPostDecideAsync(int id,string decision){if(decision is not ("approve" or "reject"))return BadRequest();try{await reviews.Decide(User.Identity.Name,id,decision=="approve");return RedirectToPage();}catch(ValidationException ex){ModelState.AddModelError("",ex.Message);await OnGetAsync();return Page();}catch(UnauthorizedAccessException){return Forbid();}}
}
